/* isry.couns.dashboard.mapper.CounsDashboardMapper.UpdateLvffcPrcs - 퇴근하기 */
MERGE INTO
AYC495 A /* 상담원출퇴근관리 */      
USING DUAL
   ON
    (
        A.CONSTT_ID     =   #{CONSTT_ID}  
    AND A.WORK_YMD      =   #{WORK_YMD} 
    )
WHEN MATCHED THEN
     UPDATE SET        
          A.LVFFC_DT        =   SYSDATE
        , A.LVFFC_IP_ADDR   =   #{LVFFC_IP_ADDR}              
        , A.LAST_MDFR_ID    =   #{LAST_MDFR_ID}
        , A.LAST_MDFCN_DT   =   SYSDATE
    WHERE A.CONSTT_ID       =   #{CONSTT_ID}  
      AND A.WORK_YMD        =   #{WORK_YMD}     
WHEN NOT MATCHED THEN 
    INSERT
        (INDEX_SN
        , CONSTT_ID
        , WORK_YMD
        , LVFFC_DT
        , LVFFC_IP_ADDR                
        , FRST_RGTR_ID
        , FRST_REG_DT
        , LAST_MDFR_ID
        , LAST_MDFCN_DT)
    VALUES
        (AYC495_SQ01.NEXTVAL
        , #{CONSTT_ID}
        , #{WORK_YMD}
        , SYSDATE
        , #{LVFFC_IP_ADDR}                
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
        , SYSDATE
        )


/* isry.couns.dashboard.mapper.CounsDashboardMapper.deleteLvffcPrcs - 상담원 퇴근하기취소 */
UPDATE AYC495 SET LVFFC_DT      = ''              
                , LAST_MDFR_ID  = #{LAST_MDFR_ID}
                , LAST_MDFCN_DT = SYSDATE
            WHERE CONSTT_ID = #{CONSTT_ID}  
              AND WORK_YMD = #{WORK_YMD}

mapper.select:
SELECT /* isry.couns.dashboard.mapper.CounsDashboardMapper.selectAtndb - 출근일시 */ TO_CHAR(MIN(A.CHG_DT), 'MM/DD HH24:MI') AS ATENDB_DT /* 전일 또는 당일 출근일시 */ FROM AYB202 A , ( SELECT USER_ID AS USER_ID /* 사용자아이디 */ , WORK_YMD AS WORK_YMD /* 근무기준일자 */ , BGNG_HR AS BGNG_HR /* 조회시작시간 */ , END_HR AS END_HR /* 조회종료시간 */ , CRTR_HR AS CRTR_HR /* 기준시간 */ , BGNG_DT - 1/24 AS BGNG_DT /* 조회시작일시 기준일시 한시간전 */ , BGNG_DT + (CRTR_HR/24) AS END_DT /* 조회시작일시 + 근무시간 */ FROM ( SELECT A.USER_ID AS USER_ID , B.BGNG_HR AS BGNG_HR , B.END_HR AS END_HR , TO_DATE(A.WORK_YMD || B.BGNG_HR , 'YYYYMMDD HH24:MI:SS') AS BGNG_DT , TO_DATE(A.WORK_YMD || B.END_HR , 'YYYYMMDD HH24:MI:SS') AS END_DT , A.WORK_YMD AS WORK_YMD
, CASE WHEN SUBSTR(B.BGNG_HR, 0, 2) > SUBSTR(B.END_HR, 0, 2) THEN (TO_NUMBER(SUBSTR(B.END_HR, 0, 2)) + 24) - TO_NUMBER(SUBSTR(B.BGNG_HR, 0, 2)) ELSE (TO_NUMBER(SUBSTR(B.END_HR, 0, 2))) - TO_NUMBER(SUBSTR(B.BGNG_HR, 0, 2)) END AS CRTR_HR
FROM AYC100 A , AYC110 B WHERE A.BIZ_PLAN_MNG_NO = B.BIZ_PLAN_MNG_NO
AND A.WORK_YMD = #{WORK_YMD}
AND A.WORK_YMD = #{P_TODAY}
AND A.USER_ID = #{CONSTT_ID} ) ) B WHERE A.CNSLTNT_ID = B.USER_ID AND A.CNSLTNT_ID = #{CONSTT_ID} AND A.DSCSN_STTS_SE_CD IN ('10','15') AND A.CHG_DT BETWEEN B.BGNG_DT AND B.END_DT

/* isry.couns.dashboard.mapper.CounsDashboardMapper.selectNoticeList 공지사항 조회 */ WITH SUB_TEMP AS (SELECT A.NTABRD_ESNTAL_NO , A.BBSCTT_ESNTAL_NO , '|'||LISTAGG (A.NTABRD_COL_ESNTAL_ID, '|') WITHIN GROUP (ORDER BY A.BBSCTT_ESNTAL_NO) AS NTABRD_COL_ESNTAL_ID_LIST , '|'||LISTAGG (A.NTABRD_COL_CN,'|') WITHIN GROUP (ORDER BY A.BBSCTT_ESNTAL_NO) AS NTABRD_COL_CN_LIST FROM ( SELECT A.NTABRD_ESNTAL_NO , A.BBSCTT_ESNTAL_NO , A.NTABRD_COL_ESNTAL_ID , A.NTABRD_COL_CN , (ROW_NUMBER () OVER (PARTITION BY A.NTABRD_ESNTAL_NO ,A.BBSCTT_ESNTAL_NO ORDER BY A.NTABRD_ESNTAL_NO, A.BBSCTT_ESNTAL_NO, A.NTABRD_COL_ESNTAL_ID )) RNUM FROM SBA120 A WHERE 1=1 AND NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO} AND NVL(A.DEL_YN, 'N') != 'Y'
) A GROUP BY A.NTABRD_ESNTAL_NO, A.BBSCTT_ESNTAL_NO ), TEMP AS (SELECT B.BBSCTT_ESNTAL_NO , B.NTABRD_ESNTAL_NO , B.BBSCTT_SN , B.BBSCTT_TTL_NM , B.BBSCTT_CN , B.FRST_REG_DT , TO_CHAR(B.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT2 , B.RDCNT_NOCS , B.FRST_RGTR_ID , C##RG.SA_FN_GET_NAME(B.FRST_RGTR_ID) AS FRST_RGTR_NM , B.ATFINO , (SELECT COUNT(MNG_SN) FROM SAB821 WHERE ATFINO = B.ATFINO AND FILE_STTS_SE_CD != 'D') AS ATFI_CNT , B.RLS_YN , B.NTC_MATTER_YN , CASE WHEN TRUNC(SYSDATE - B.FRST_REG_DT) > 1 THEN 'N' ELSE 'Y' END AS NEW_BBSCTT , A.NTABRD_COL_ESNTAL_ID_LIST , A.NTABRD_COL_CN_LIST FROM SUB_TEMP A, SBA110 B WHERE 1=1 AND B.NTABRD_ESNTAL_NO = #{NTABRD_ESNTAL_NO} AND A.BBSCTT_ESNTAL_NO(+) = B.BBSCTT_ESNTAL_NO AND A.NTABRD_ESNTAL_NO(+) = B.NTABRD_ESNTAL_NO AND NVL(B.DEL_YN, 'N') != 'Y' ORDER BY BBSCTT_ESNTAL_NO DESC ) SELECT A.NUM AS NUM , A.FRST_REG_DT AS FRST_REG_DT , A.BBSCTT_TTL_NM AS BBSCTT_TTL_NM FROM ( SELECT ROW_NUMBER() OVER( ORDER BY T.FRST_REG_DT DESC ) AS NUM /* 정렬순서 */ , TO_CHAR(T.FRST_REG_DT, 'YYYY.MM.DD') AS FRST_REG_DT /* 작성일 */ , T.BBSCTT_TTL_NM AS BBSCTT_TTL_NM /* 제목 */ FROM ( SELECT A.* , 'Y' AS HIGH_LIGHT_YN FROM TEMP A WHERE NTC_MATTER_YN = 'Y' UNION ALL SELECT B.* , 'N' AS HIGH_LIGHT_YN FROM TEMP B ) T ) A
ORDER BY NUM

    /* 
     * isry.couns.dashboard.mapper.CounsDashboardMapper.selectCnsltntTaskwkReprtCount : AYC300(업무보고서)데이터 존재 여부
     */
	    SELECT
	            COUNT(*)
	    FROM
	            AYC300
	    WHERE   1=1
	    AND     CNSLTNT_ID   =   #{CONSTT_ID}
	    AND     WORK_YMD    =   #{WORK_YMD}

/* * isry.couns.dashboard.mapper.CounsDashboardMapper.selectTodayWorkInfoByCnsltnt : 상담원 오늘 근무 정보 조회 */ WITH TMP AS ( SELECT MAX(T1.WORK_YMD) AS WORK_YMD FROM ( SELECT TO_DATE(A.WORK_YMD || REPLACE(B.BGNG_HR, ':', '') || '00', 'YYYYMMDDHH24MISS') - 1/12 AS WORK_DT , WORK_YMD AS WORK_YMD FROM AYC100 A , AYC110 B WHERE 1=1 AND B.BIZ_PLAN_MNG_NO = A.BIZ_PLAN_MNG_NO AND A.USER_ID = #{CONSTT_ID} ) T1
WHERE T1.WORK_DT < SYSDATE
) SELECT NVL(T.WORK_YMD, TO_CHAR(SYSDATE, 'YYYYMMDD')) AS WORK_YMD , NVL(TO_CHAR(T.WK_START_DT, 'YYYYMMDDHH24MISS'), TO_DATE(TO_CHAR(SYSDATE, 'YYYYMMDD') || '000000','YYYYMMDDHH24MISS')) AS WK_START_DT , NVL(TO_CHAR(T.WK_END_DT, 'YYYYMMDDHH24MISS'), TO_DATE(TO_CHAR(SYSDATE, 'YYYYMMDD') || '000000','YYYYMMDDHH24MISS')) AS WK_END_DT FROM ( SELECT A.WORK_YMD AS WORK_YMD , TO_DATE(A.WORK_YMD || ' ' || B.BGNG_HR, 'YYYY-MM-DD HH24:MI:SS') - (INTERVAL '2' HOUR) AS WK_START_DT , TO_DATE(A.WORK_YMD || ' ' || B.BGNG_HR, 'YYYY-MM-DD HH24:MI:SS') + (INTERVAL '6' HOUR) AS WK_END_DT FROM AYC100 A , AYC110 B , TMP WHERE A.BIZ_PLAN_MNG_NO = B.BIZ_PLAN_MNG_NO AND A.WORK_YMD = TMP.WORK_YMD AND A.USER_ID = #{CONSTT_ID} ) T
